CSS = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0b1410;color:#edf3e9;font:17px/1.7 system-ui,sans-serif}a{color:#b8d9a9}header{padding:70px max(5vw,24px);background:linear-gradient(120deg,#275D38,#12251a);border-bottom:1px solid #58714f}header p{max-width:760px;color:#d1ddc8}h1,h2,h3{font-family:Georgia,serif;line-height:1.2}h1{font-size:clamp(2.4rem,5vw,4.5rem);letter-spacing:-.04em;margin:15px 0}h2{font-size:2rem;margin-top:0}h3{font-size:1.35rem}.kicker{font-size:.75rem;letter-spacing:.2em;color:#d2ddb7;text-transform:uppercase}.layout{display:grid;grid-template-columns:240px minmax(0,950px);gap:48px;max-width:1320px;margin:auto;padding:48px 30px}nav{position:sticky;top:24px;align-self:start}nav a{display:block;padding:8px 0;text-decoration:none;font-size:.88rem;border-bottom:1px solid #293e2d}section{margin:0 0 60px;scroll-margin-top:30px}.note{background:#192c20;border-left:4px solid #a6b980;padding:20px;margin:24px 0}table{width:100%;border-collapse:collapse;font-size:.92rem;margin:24px 0}th{text-align:left;background:#275D38}th,td{padding:14px;border:1px solid #36503b;vertical-align:top}tr:nth-child(even){background:#14221a}pre{background:#15241b;border:1px solid #36503b;padding:22px;border-radius:12px;overflow:auto;color:#d2e4c6;font:14px/1.6 ui-monospace,monospace}code{color:#c1dbb1}figure{margin:28px 0;background:#122018;border:1px solid #36503b;padding:20px;border-radius:16px}svg{width:100%;height:auto;display:block}figcaption{font-size:.85rem;color:#b9cab2;margin-top:16px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#15271c;border:1px solid #3b5740;padding:20px;border-radius:12px}.card strong{display:block;color:#c3d9ab;font-size:1.4rem}footer{border-top:1px solid #34503a;padding:28px 5vw;color:#b1c1ab;font-size:.9rem}@media(max-width:850px){.layout{display:block;padding:30px 20px}nav{position:static;margin-bottom:40px}.cards{grid-template-columns:1fr}table{display:block;overflow:auto}}@media print{body{background:white;color:#18211a;font-size:11pt}header{background:#e1eddf;color:#17241a;padding:30px}header p,a,code{color:#245534}.layout{display:block;padding:20px}nav{display:none}figure,.card,pre,.note{background:#eef3eb;color:#15251b}th{background:#d7e6d2}section{break-inside:avoid}svg text{fill:#182b1d}footer{color:#18211a}}'''

def table(headers, rows):
    return '<table><thead><tr>'+''.join('<th>'+escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'

def diagram(title, nodes, edges, caption, height=340):
    svg = f'<svg viewBox="0 0 900 {height}" role="img" aria-label="{escape(title)}"><title>{escape(title)}</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#adc593"/></marker></defs>'
    for a,b,label in edges:
        x,y,_,_=nodes[a]; xx,yy,_,_=nodes[b]
        horizontal=abs(xx-x)>abs(yy-y)
        if horizontal:
            sign=1 if xx>x else -1
            x1,x2,y1,y2=x+sign*80,xx-sign*80,y,yy
        else:
            sign=1 if yy>y else -1
            x1,x2,y1,y2=x,xx,y+sign*29,yy-sign*29
        svg+=f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#adc593" stroke-width="2" marker-end="url(#arrow)"/><text x="{(x1+x2)/2}" y="{(y1+y2)/2-10}" text-anchor="middle" fill="#c8d6ba" font-size="12">{escape(label)}</text>'
    for x,y,label,sub in nodes:
        svg+=f'<rect x="{x-80}" y="{y-29}" width="160" height="58" rx="10" fill="#275D38" stroke="#8ca77d"/><text x="{x}" y="{y-3}" text-anchor="middle" fill="#fff" font-size="14" font-family="system-ui">{escape(label)}</text><text x="{x}" y="{y+17}" text-anchor="middle" fill="#d9e6d1" font-size="11" font-family="system-ui">{escape(sub)}</text>'
    return '<figure>'+svg+'</svg><figcaption>'+caption+'</figcaption></figure>'

